function setSubclass(charId, value) {
  const ch = state.characters.find(x => x.id === charId);
  if (!ch) return;
  ch.subclass = value;
  save();
  refreshSheets();
}

// Weapon proficiency checker: returns true if class can use weapon
function classCanUseWeapon(classId, weapon) {
  const cls = CLASSES.find(c => c.id === classId);
  if (!cls) return false;
  if (cls.weaponProf === 'all') return true;
  const profs = cls.weaponProf.split(',').map(s => s.trim());
  if (profs.includes('simple') && weapon.weight === 'Simple') return true;
  if (profs.includes('martial') && weapon.weight === 'Martial') return true;
  if (profs.includes(weapon.id)) return true;
  return false;
}

// Spell slot limits by class and level
function getSpellAllowances(classId, charLevel) {
  const cls = CLASSES.find(c => c.id === classId);
  if (!cls || !cls.spellcaster || !cls.spellSlots) return null;
  const lvlIdx = Math.min(charLevel - 1, 19);
  const slots = cls.spellSlots[lvlIdx];
  const cantrips = cls.cantripsKnown ? cls.cantripsKnown[lvlIdx] : 0;
  const spellsKnown = cls.spellsKnown ? cls.spellsKnown[lvlIdx] : null; // null = prepared caster (all)
  return { slots, cantrips, spellsKnown };
}

// Returns how many spells of each level a caster can know/prepare
function getSpellLimits(classId, charLevel, stats) {
  const cls = CLASSES.find(c => c.id === classId);
  if (!cls || !cls.spellcaster) return null;
  const allowances = getSpellAllowances(classId, charLevel);
  if (!allowances) return null;
  
  const result = { cantrips: allowances.cantrips, byLevel: {} };
  
  if (allowances.spellsKnown !== null) {
    // Known caster (bard, sorcerer, warlock, ranger, paladin) - limited total known spells
    result.totalKnown = allowances.spellsKnown;
    result.isPrepared = false;
  } else {
    // Prepared caster (cleric, druid, wizard, artificer) - level + modifier spells prepared
    const modStat = cls.statHp; // reuse this field to find spellcasting mod
    const spellMod = stats ? Math.floor(((stats[modStat] || 10) - 10) / 2) : 0;
    result.totalKnown = Math.max(1, charLevel + spellMod);
    result.isPrepared = true;
  }
  
  return result;
}

